# --- Figure 4: win rate required to break even vs round-trip cost as a share of risk ---
COSTS = [i * 2.5 for i in range(21)]  # 0% .. 50% of R
def needed(target_r, c):
    # p*T - (1-p)*1 - c > 0  =>  p > (1 + c) / (T + 1), with c in R units
    return 100 * (1 + c / 100) / (target_r + 1)
line_chart(
    "cost-vs-win-rate.svg",
    {"target 0.5R (scalp)": [needed(0.5, c) for c in COSTS],
     "target 1R": [needed(1.0, c) for c in COSTS],
     "target 2R": [needed(2.0, c) for c in COSTS]},
    title="Break-even win rate vs round-trip cost (cost as % of risk per trade)",
    y_label="win rate needed, %", x_labels=[f"{c:.0f}%" for c in COSTS],
    y_fmt=lambda v: f"{v:.0f}%",
)

# --- Figure 5: the daily risk routine ---
